import copy
from lxml import etree
W='{http://schemas.openxmlformats.org/wordprocessingml/2006/main}'
XML='{http://www.w3.org/XML/1998/namespace}'

tree=etree.parse('m/word/document.xml')
body=tree.getroot().find(W+'body')
target=None
for p in body.iter(W+'p'):
    if ''.join(p.itertext()).startswith('This study revealed that the prevalence'):
        target=p; break
assert target is not None

children=list(target)
pPr=children[0] if etree.QName(children[0]).localname=='pPr' else None

# --- collect field blocks (outermost fldChar begin ... matching end), and tracked changes
fields=[]   # list of lists of elements
tracked=[]  # del/ins elements in order
proto_run=None
blocks=[]   # ordered blocks: ('text', str) | ('field', [els]) | ('tracked', el)
depth=0
cur=None
for c in children:
    tag=etree.QName(c).localname
    if pPr is not None and c is pPr: continue
    if tag=='r':
        fc=c.find(W+'fldChar')
        if fc is not None:
            typ=fc.get(W+'fldCharType')
            if typ=='begin':
                depth+=1
                if depth==1: cur=[]
            if cur is not None: cur.append(c)
            if typ=='end':
                depth-=1
                if depth==0:
                    fields.append(cur); cur=None
            continue
        if cur is not None:
            cur.append(c); continue
        # plain run
        if proto_run is None and c.find(W+'rPr') is None:
            proto_run=c
        txt=''.join(t.text or '' for t in c.iter(W+'t'))
        blocks.append(('text',txt))
    elif tag in ('del','ins'):
        if cur is not None: cur.append(c)
        else:
            tracked.append(c); blocks.append(('tracked',c))
    elif tag in ('commentRangeStart','commentRangeEnd','commentReference','bookmarkStart','bookmarkEnd'):
        raise SystemExit('unexpected marker in target paragraph: '+tag)
